export function getPlantsByCountry(countryCode: string): BiomethanePlant[] {
  return BIOMETHANE_PLANTS.filter(p => p.countryCode === countryCode);
}

export function searchPlants(query: string): BiomethanePlant[] {
  const q = query.toLowerCase();
  return BIOMETHANE_PLANTS.filter(p => 
    p.name.toLowerCase().includes(q) ||
    p.country.toLowerCase().includes(q) ||
    (p.operator && p.operator.toLowerCase().includes(q)) ||
    (p.primaryFeedstockCategory && p.primaryFeedstockCategory.toLowerCase().includes(q)) ||
    (p.upgradingTechnology && p.upgradingTechnology.toLowerCase().includes(q)) ||
    (p.region && p.region.toLowerCase().includes(q)) ||
    (p.networkOperator && p.networkOperator.toLowerCase().includes(q))
  );
}
